<?php
/** @var string $base @var string $csrf @var array $ticket @var array $messages @var array $statuses @var array $categories */
$e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
?>
<div class="mb-3"><a class="small text-decoration-none" href="<?= $e($base) ?>/admin/support">← Kembali ke inbox</a></div>
<div class="row g-3">
  <section class="col-xl-8"><div class="card"><div class="card-header d-flex justify-content-between align-items-start gap-3"><div><h2 class="h5 mb-1"><?= $e($ticket['subject']) ?></h2><div class="small text-muted">#<?= $e($ticket['ticket_no']) ?> · <?= $e($categories[$ticket['category']]??$ticket['category']) ?></div></div><form method="post" action="<?= $e($base) ?>/admin/support/status" class="d-flex gap-2"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><label class="visually-hidden" for="ticketStatus">Status tiket</label><select class="form-select form-select-sm" id="ticketStatus" name="status"><?php foreach($statuses as $key=>$label): ?><option value="<?= $e($key) ?>" <?= $ticket['status']===$key?'selected':'' ?>><?= $e($label) ?></option><?php endforeach; ?></select><button class="btn btn-outline-primary btn-sm">Simpan</button></form></div>
    <div class="card-body"><div class="d-grid gap-3"><?php foreach($messages as $message): $isAdmin=$message['sender_role']==='super_admin'; ?><article class="p-3 border rounded-2 <?= $isAdmin?'bg-light':'' ?>"><div class="d-flex justify-content-between gap-2"><strong><?= $e($message['sender_name']) ?> <span class="small fw-normal text-muted">· <?= $isAdmin?'Admin':'Owner' ?></span></strong><time class="small text-muted"><?= $e(date('d M Y, H:i',strtotime((string)$message['created_at']))) ?></time></div><div class="mt-2 text-break" style="white-space:pre-wrap"><?= $e($message['body']) ?></div></article><?php endforeach; ?></div></div>
    <form method="post" action="<?= $e($base) ?>/admin/support/reply" class="card-footer"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><label class="form-label small fw-semibold" for="adminReply">Balas owner</label><textarea class="form-control mb-2" id="adminReply" name="body" rows="4" minlength="2" maxlength="5000" required></textarea><button class="btn btn-primary btn-sm">Kirim balasan</button></form>
  </div></section>
  <aside class="col-xl-4"><div class="card"><div class="card-header fw-semibold">Detail tiket</div><dl class="card-body mb-0"><dt class="small text-muted">Owner</dt><dd><?= $e($ticket['owner_name']) ?><div class="small text-muted"><?= $e($ticket['owner_email']) ?></div></dd><dt class="small text-muted">Usaha terkait</dt><dd><?= $e($ticket['tenant_name']) ?></dd><dt class="small text-muted">Invoice</dt><dd><?php if($ticket['invoice_no']): ?><a href="<?= $e($base) ?>/admin/billing/invoice?id=<?= (int)$ticket['invoice_id'] ?>"><?= $e($ticket['invoice_no']) ?></a><?php else: ?>Tidak ada<?php endif; ?></dd><dt class="small text-muted">Dibuat</dt><dd><?= $e(date('d M Y, H:i',strtotime((string)$ticket['created_at']))) ?></dd></dl></div></aside>
</div>